 ('mc', 5, 'esma', 'Esmâ', 'm', 'Hicret sırasında Sevr mağarasına yiyecek taşıyan ve kemerini ikiye bölüp azığı bağlayan sahabe hanım kimdir?', 'Esmâ binti Ebû Bekir', ['Hafsa binti Ömer', 'Ümmü Seleme', 'Zeyneb binti Cahş'], 'Bu yüzden “iki kuşaklı” anlamında Zâtü’n-nitâkayn diye anılır (Buhârî).'),
 ('mc', 5, 'ummu_seleme', 'Ümmü Seleme', 'h', 'Hudeybiye’de sahabeler kurbanlarını kesmekte tereddüt edince Hz. Peygamber’e “Sen önce kes” diye akıllıca tavsiyede bulunan eşi kimdir?', 'Ümmü Seleme', ['Hatice', 'Sevde', 'Meymûne'], 'Hz. Peygamber kurbanını kesip tıraş olunca sahabeler de hemen ona uydu (Buhârî).'),
 ('mc', 5, 'sumeyye_tekrar', 'Sümeyye', 'm', 'Sümeyye hangi yönüyle hatırlanır?', 'İslam’ın ilk şehidi olmasıyla', ['İlk halife olmasıyla', 'İlk müezzin olmasıyla', 'Kur’an’ı toplamasıyla'], 'Sümeyye işkence altında imanından dönmedi ve şehit oldu.'),
 ('mc', 5, 'hatice_destek', 'Hz. Hatice’nin desteği', 'm', 'Hz. Hatice, Hz. Peygamber’e en çok hangi yönden destek oldu?', 'İlk iman eden olarak manevi destek verdi ve malını davete harcadı', ['Ona hiç destek olmadı', 'Onu Mekke’den kovdu', 'Ona karşı çıktı'], 'Hz. Peygamber “İnsanlar beni yalanladığında o beni tasdik etti” buyurdu (Ahmed b. Hanbel).'),
 ('mc', 5, 'kadin_ilim', 'Kadınların ilmi', 'm', 'Sahabe hanımlar ilim konusunda nasıl bir yol izledi?', 'Hz. Peygamber’den öğrenmek için ayrı ders günü istediler', ['İlimden tamamen uzak durdular', 'Sadece şiir öğrendiler', 'Hiç soru sormadılar'], 'Hanımların isteği üzerine Hz. Peygamber onlara özel bir gün ayırdı (Buhârî).'),
 ('tf', 5, 'aise_soru', 'Hz. Âişe’ye danışma', 'm', 'Hz. Peygamber’in vefatından sonra sahabeler birçok dinî meselede Hz. Âişe’ye danışırdı.', True, 'Hz. Âişe ilmi ve keskin zekâsıyla bir başvuru kaynağıydı.'),
 ('tf', 5, 'sifa_hanim', 'Şifâ binti Abdullah', 'h', 'Şifâ binti Abdullah okuma yazma bilen ve bunu başkalarına öğreten bir sahabe hanımdı.', True, 'Hz. Peygamber, Şifâ’dan eşi Hafsa’ya yazı öğretmesini istemiştir (Ebû Dâvûd).'),
 ('sc', 5, 'sc_esma', 'Cesaret', 'm', 'Esmâ binti Ebû Bekir, Ebû Cehil tokat atmasına rağmen hicret edenlerin yerini söylemedi. Bu bize ne öğretir?', 'Emanete sadakati ve doğru yolda cesur olmayı', ['Sırları herkese söylemeyi', 'Korkunca her şeyi anlatmayı', 'Yardım etmemeyi'], 'Esmâ, Ebû Cehil’in tokadına rağmen sırrı korudu.'),
 ('sc', 5, 'sc_ummu_seleme', 'İstişarenin değeri', 'h', 'Hz. Peygamber’in Ümmü Seleme’nin tavsiyesini dinlemesi neyi gösterir?', 'Güzel fikirlere kim söylerse söylesin değer verildiğini', ['Kadınların fikir belirtemeyeceğini', 'Tavsiyenin gereksiz olduğunu', 'Liderin hiç danışmaması gerektiğini'], 'Hz. Peygamber eşinin akıllıca önerisini uyguladı ve sorun çözüldü.'),
 ('fb', 5, 'fb_nitakayn', 'İki kuşaklı', 'h', 'Esmâ binti Ebû Bekir “Zâtü’n-___” lakabıyla anılır.', 'nitâkayn', ['nûreyn', 'kıbleteyn', 'harameyn'], 'İki kuşak sahibi demektir.'),
 ('fb', 5, 'fb_umare', 'Uhud’un kahramanı', 'm', 'Uhud’da Hz. Peygamber’i savunan Nüseybe, Ümmü ___ künyesiyle bilinir.', 'Umâre', ['Gülsüm', 'Eymen', 'Seleme'], 'Nüseybe binti Kâ‘b, Ümmü Umâre diye anılır.'),
 ('pr', 5, 'pr_aise_ilim', 'Hz. Âişe', 'm', 'Hz. Âişe’nin en belirgin özelliği ___ idi.', 'ilmi', 'Hz. Âişe çok sayıda hadis rivayet etmiş, sahabeye öğretmenlik yapmıştır.'),
 ('mt', 5, 'hanim_esle', 'Sahabe hanımlar', 'h', 'Sahabe hanımları özellikleriyle eşleştir:', [('Hatice', 'İlk iman eden'), ('Âişe', 'İlmi ve hadis rivayeti'), ('Esmâ', 'Hicrette yiyecek taşıyan'), ('Nüseybe', 'Uhud’da Peygamber’i savunan')], 'Sahabe hanımlar imanda, ilimde ve cesarette örnektir.'),
 ('es', 5, 'es_kadin_ilim', 'Kadın ve ilim', 'm', 'Sahabe döneminde kadınlar ilimle hiç ilgilenmezdi.', 'Sahabe hanımlar ilme önem verdi; Hz. Âişe gibi büyük âlimler yetişti', ['Kadınların okuması yasaktı', 'Sadece erkekler hadis rivayet etti', 'Kadınlar mescide hiç gelemezdi'], 'Hanımlar Hz. Peygamber’den ders istedi ve hadis rivayet etti.'),
 ('tf', 5, 'sevde', 'Hz. Sevde', 'h', 'Hz. Sevde, Hz. Hatice’nin vefatından sonra Hz. Peygamber’in evlendiği eşidir.', True, 'Hz. Sevde ilk Müslümanlardandı ve Habeşistan’a da hicret etmişti.'),

 # S6 — Akıllı Tekrar (12)
 ('sr', 6, 'sr_ilk_halife', 'Halife', 'e', 'İlk halife kimdir?', 'Ebû Bekir', ['Ömer', 'Osman', 'Ali'], 'Hz. Ebû Bekir ilk halifedir.'),
 ('sr', 6, 'sr_faruk', 'Fârûk', 'm', '“Fârûk” kimin lakabıdır?', 'Hz. Ömer', ['Hz. Ali', 'Hz. Osman', 'Hz. Hamza'], 'Hakkı batıldan ayıran Hz. Ömer.'),
 ('sr', 6, 'sr_zinnureyn', 'Zinnûreyn', 'm', '“Zinnûreyn” kimin lakabıdır?', 'Hz. Osman', ['Hz. Ebû Bekir', 'Hz. Ali', 'Hz. Abbas'], 'Peygamber’in iki kızıyla evlenen Hz. Osman.'),
 ('sr', 6, 'sr_hadis', 'Hadis', 'm', 'En çok hadis rivayet eden sahabe kimdir?', 'Ebû Hüreyre', ['Hâlid', 'Bilâl', 'Selmân'], 'Ebû Hüreyre en çok hadis rivayet edendir.'),
 ('tf', 6, 'tf_tekrar_hasan', 'Torunlar', 'e', 'Hz. Hasan ve Hz. Hüseyin, Hz. Fâtıma’nın oğullarıdır.', True, 'Hz. Fâtıma ve Hz. Ali’nin oğullarıdır.'),
 ('tf', 6, 'tf_tekrar_aise_omer', 'Hz. Âişe', 'm', 'Hz. Âişe, Hz. Ömer’in kızıdır.', False, 'Hz. Âişe, Hz. Ebû Bekir’in kızıdır; Hz. Hafsa, Hz. Ömer’in kızıdır.'),
 ('tf', 6, 'tf_tekrar_esma', 'Esmâ', 'm', 'Esmâ binti Ebû Bekir hicrette mağaraya yiyecek taşıdı.', True, 'Bu yüzden Zâtü’n-nitâkayn diye anılır.'),
 ('mc', 6, 'mc_tekrar_seyfullah', 'Seyfullah', 'm', '“Allah’ın kılıcı” kimdir?', 'Hâlid b. Velîd', ['Ebû Ubeyde', 'Muâz', 'Mus‘ab'], 'Hâlid b. Velîd.'),
 ('mc', 6, 'mc_tekrar_emin', 'Ümmetin emini', 'h', '“Bu ümmetin emini” kimdir?', 'Ebû Ubeyde b. Cerrâh', ['Hâlid b. Velîd', 'Ebû Hüreyre', 'Amr b. Âs'], 'Ebû Ubeyde b. Cerrâh.'),
 ('mc', 6, 'mc_tekrar_mumin_anne', 'Müminlerin anneleri', 'm', 'Hz. Peygamber’in eşlerine ne denir?', 'Müminlerin anneleri', ['Tâbiûn', 'Ensar', 'Muhacir'], 'Ahzâb 33:6.'),
 ('es', 6, 'es_tekrar_ali_ilk_halife', 'Halife sırası', 'm', 'İlk halife Hz. Ali’dir.', 'İlk halife Hz. Ebû Bekir’dir; Hz. Ali dördüncü halifedir', ['İlk halife Hz. Osman’dır', 'Halife hiç seçilmedi', 'İlk halife Hz. Hamza’dır'], 'Sıra: Ebû Bekir, Ömer, Osman, Ali.'),
 ('es', 6, 'es_tekrar_osman_kizlar', 'Zinnûreyn', 'h', 'Hz. Osman’a iki şehir kurduğu için Zinnûreyn denir.', 'Hz. Osman Peygamber’in iki kızıyla evlendiği için Zinnûreyn diye anılır', ['İki kez halife seçildiği için', 'İki dil bildiği için', 'İki savaş kazandığı için'], 'Rukıyye ve Ümmü Gülsüm ile evlendi.'),

 # S7 — Ünite Challenge (14)
 ('sc', 7, 'ch_comertlik', 'Cömertlik', 'm', 'Okulda su sebili bozulmuş, herkes zorlanıyor. Hz. Osman’ın hangi davranışı burada örnek olabilir?', 'Rûme kuyusunu alıp herkese bağışlaması', ['Hiçbir şeye karışmaması', 'Suyu satması', 'Sadece kendine su alması'], 'Hz. Osman halkın ihtiyacını görüp kuyuyu herkese açtı.'),
 ('sc', 7, 'ch_adalet', 'Adalet', 'm', 'Sınıf başkanı yakın arkadaşına ayrıcalık tanıyor. Hz. Ömer’in tutumu ne öğretir?', 'Adaletin herkes için eşit uygulanmasını', ['Arkadaşlara ayrıcalık tanınmasını', 'Kuralların önemsiz olduğunu', 'Güçlünün haklı olduğunu'], 'Hz. Ömer adaletiyle tanınır; kimseye ayrıcalık tanımazdı.'),
 ('sc', 7, 'ch_tasdik', 'Güven', 'h', 'Hz. Ebû Bekir’in Mi‘râc haberine “O söylediyse doğrudur” demesi neyi gösterir?', 'Hz. Peygamber’e duyduğu derin güveni ve sadakati', ['Düşünmeden her şeye inandığını', 'Peygamber’e güvenmediğini', 'Olaydan haberi olmadığını'], 'Sıddîk lakabı bu sadakatten gelir.'),
 ('es', 7, 'ch_es_bilal_omer', 'Bilâl’in özgürlüğü', 'm', 'Hz. Bilâl’i satın alıp azat eden Hz. Osman’dır.', 'Hz. Bilâl’i satın alıp azat eden Hz. Ebû Bekir’dir', ['Bilâl hiç köle olmadı', 'Bilâl’i Ebû Cehil azat etti', 'Bilâl’i Hâlid azat etti'], 'Hz. Ebû Bekir onu işkenceden kurtardı.'),
 ('es', 7, 'ch_es_fatima_aise', 'Aile', 'h', 'Hz. Fâtıma, Hz. Ebû Bekir’in kızıdır.', 'Hz. Fâtıma, Hz. Peygamber ile Hz. Hatice’nin kızıdır', ['Hz. Fâtıma Hz. Ömer’in kızıdır', 'Hz. Fâtıma Hz. Ali’nin kızıdır', 'Hz. Fâtıma Hz. Osman’ın kızıdır'], 'Hz. Âişe, Hz. Ebû Bekir’in kızıdır.'),
 ('pr', 7, 'ch_pr_tabiun', 'Sonraki nesil', 'm', 'Sahabeyi görüp onlardan öğrenen nesle ___ denir.', 'tâbiûn', 'Tâbiûn, takip edenler demektir.'),
 ('pr', 7, 'ch_pr_zehra', 'Lakap', 'm', 'Hz. Fâtıma’nın lakabı ez-___’dır.', 'Zehrâ', 'Zehrâ, nurlu yüzlü demektir.'),
 ('pr', 7, 'ch_pr_esedullah', 'Allah’ın aslanı', 'h', 'Hz. Ali’nin “Allah’ın aslanı” anlamındaki lakabı ___ dır.', 'Esedullah', 'Hz. Ali cesaretiyle bilinir.'),
 ('mc', 7, 'ch_halife_sira', 'Kronoloji', 'h', 'Aşağıdakilerden hangisi doğru halife sırasıdır?', 'Ebû Bekir, Ömer, Osman, Ali', ['Ali, Osman, Ömer, Ebû Bekir', 'Ömer, Ebû Bekir, Ali, Osman', 'Osman, Ali, Ebû Bekir, Ömer'], 'Hulefâ-i Râşidîn bu sırayla görev yaptı.'),
 ('mc', 7, 'ch_kuran_hafsa', 'Kur’an sayfaları', 'h', 'Hz. Ebû Bekir döneminde toplanan Kur’an sayfaları sonra kimin yanında korundu?', 'Hz. Hafsa’nın', ['Hz. Fâtıma’nın', 'Hz. Esmâ’nın', 'Hz. Sevde’nin'], 'Hz. Osman çoğaltma sırasında bu sayfalardan yararlandı (Buhârî).'),
 ('mt', 7, 'ch_mt_lakap', 'Lakaplar', 'h', 'Kişileri lakaplarıyla eşleştir:', [('Ebû Bekir', 'Sıddîk'), ('Hâlid b. Velîd', 'Seyfullah'), ('Fâtıma', 'Zehrâ'), ('Esmâ', 'Zâtü’n-nitâkayn')], 'Lakaplar kişilerin öne çıkan özelliklerini yansıtır.'),
 ('mt', 7, 'ch_mt_olay', 'Olaylar', 'm', 'Sahabeleri olaylarla eşleştir:', [('Osman', 'Rûme kuyusu'), ('Ömer', 'Kudüs’ün barışla alınması'), ('Ali', 'Hicret gecesi Peygamber’in yatağı'), ('Ümmü Seleme', 'Hudeybiye’deki tavsiye')], 'Her sahabenin hayatında örnek olaylar vardır.'),
 ('sc', 7, 'ch_saygi', 'Saygı', 'm', 'Biri sohbet ederken sahabeler hakkında alaycı ve kırıcı sözler söylüyor. En doğru tutum hangisidir?', 'Saygılı bir dille sahabenin İslam’a hizmetini hatırlatmak', ['Onunla birlikte alay etmek', 'Kavga etmek', 'Hiçbir şey hissetmemek'], 'Haşr 59:10’da önceki müminler için dua etmek ve onlara karşı kalpte kin taşımamak istenir.'),
 ('tf', 7, 'ch_tf_ebu_eyyub', 'Ebû Eyyûb', 'm', 'Ebû Eyyûb el-Ensârî’nin kabri İstanbul’dadır.', True, 'İstanbul kuşatmasında vefat edip surların dibine defnedildi.'),
